&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;T&amp;Uuml;RKİYE&amp;rsquo;Yİ&amp;nbsp;SEFALET&amp;nbsp;ENDEKSİNDE&amp;nbsp;D&amp;Uuml;NYA 3.&amp;rsquo;S&amp;Uuml; YAPTINIZ&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Ccedil;ocuk &amp;ccedil;ocuk diyorsunuz da o &amp;ccedil;ocuklarımız nasıl bir&amp;nbsp;T&amp;uuml;rkiye&amp;rsquo;de d&amp;uuml;nyaya&amp;nbsp;geliyorlar? &amp;Ccedil;ocuklarımızın yaşadıklarını&amp;nbsp;anlamlandırmak i&amp;ccedil;in&amp;nbsp;&amp;ouml;yle&amp;nbsp;uzun uzun teori&amp;nbsp;anlatmaya&amp;nbsp;gerek yok. T&amp;uuml;rkiye,&amp;nbsp;bug&amp;uuml;n D&amp;uuml;nya sefalet endeksinde &amp;uuml;&amp;ccedil;&amp;uuml;nc&amp;uuml; sırada. Şu tabloya&amp;nbsp;bakar mısınız?&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

